package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class NumericEntityUnescaper_ESTest_test4 extends NumericEntityUnescaper_ESTest_scaffolding {

    /**
     * When the unescaper is created with no OPTIONs it defaults to "semicolon required".
     * The input begins with the hex entity prefix "&#x" but is not followed by any hex
     * digits or a terminating semicolon, so it is not a valid numeric entity. As a result
     * the translator leaves the input completely unchanged and returns it verbatim,
     * including the seven trailing NUL ('�') padding characters of the backing array.
     */
    @Test(timeout = 4000)
    public void translateLeavesIncompleteHexEntityUnchanged() throws Throwable {
        NumericEntityUnescaper.OPTION[] noOptions = new NumericEntityUnescaper.OPTION[0];
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper(noOptions);

        // A 10-char buffer whose first three chars are the hex-entity prefix "&#x";
        // the remaining seven chars stay at their default value '�' (NUL).
        char[] input = new char[10];
        input[0] = '&';
        input[1] = '#';
        input[2] = 'x';
        CharBuffer inputSequence = CharBuffer.wrap(input);

        String result = unescaper.translate((CharSequence) inputSequence);

        // Unchanged input: the "&#x" prefix followed by the seven default NUL chars.
        String sevenNulChars = new String(new char[7]);
        assertEquals("&#x" + sevenNulChars, result);
    }
}
